// workspace.layer_control_oracle — replay of the frozen Python product
// oracle (fixtures/layer_control_oracle.json, generated by
// tools/oracle/generate_layer_control_fixtures.py). QGIS-native layer
// control convergence: the order-key/tree/diff vocabularies retired with
// the second layer tree (QgsLayerTree is the runtime authority); the
// surviving codec/behavior vocabularies stay under parity —
// source_usage + stage view state behavior.
#include "compare_json.hpp"
#include "pwb_test.hpp"

#include "pwb/workspace/source_usage.hpp"
#include "pwb/workspace/state.hpp"
#include "pwb/workspace/state_ops.hpp"

#include <algorithm>
#include <cstdlib>
#include <fstream>
#include <sstream>
#include <tuple>

namespace {

using pwb::domain::Json;
using pwb_test::json_compare;

const Json& oracle() {
    static Json cached = [] {
        const char* dir = std::getenv("PWB_WORKSPACE_FIXTURE_DIR");
        const std::string path = dir != nullptr
                                     ? std::string(dir) +
                                           "/layer_control_oracle.json"
                                     : std::string(
                                           PWB_WORKSPACE_FIXTURE_DIR) +
                                           "/layer_control_oracle.json";
        std::ifstream in(path);
        if (!in) {
            std::cerr << "cannot open oracle fixture: " << path << "\n";
            std::abort();
        }
        Json data = Json::parse(in);
        if (data.value("schema", std::string()) !=
            "pwb.workspace.layer_control.oracle/1") {
            std::cerr << "oracle schema mismatch: " << path << "\n";
            std::abort();
        }
        return data;
    }();
    return cached;
}

std::map<std::string, std::string> json_to_map(const Json& data) {
    std::map<std::string, std::string> out;
    if (!data.is_object()) return out;
    for (auto it = data.begin(); it != data.end(); ++it) {
        // null / non-string values count as absent (Python filters
        // non-str keys before use).
        if (it.value().is_string()) {
            out[it.key()] = it.value().get<std::string>();
        }
    }
    return out;
}

Json map_to_json(const std::map<std::string, std::string>& data) {
    Json out = Json::object();
    for (const auto& [key, value] : data) out[key] = value;
    return out;
}

class FakeCatalog : public pwb::workspace::UsageCatalog {
public:
    explicit FakeCatalog(const Json& data)
        : run_inputs_(data["run_inputs"]),
          runs_consuming_(data["runs_consuming"]),
          versions_by_asset_(data["versions_by_asset"]),
          run_meta_(data["run_meta"]) {}

    std::optional<std::vector<std::string>> run_input_version_ids(
        const std::string& run_id) const override {
        if (!run_meta_.contains(run_id)) return std::nullopt;
        if (!run_inputs_.contains(run_id)) {
            return std::vector<std::string>{};
        }
        std::vector<std::string> out;
        for (const auto& vid : run_inputs_[run_id]) {
            out.push_back(vid.get<std::string>());
        }
        return out;
    }

    std::vector<pwb::workspace::RunSummary> runs_consuming(
        const std::string& version_id) const override {
        std::vector<pwb::workspace::RunSummary> out;
        if (!runs_consuming_.contains(version_id)) return out;
        for (const auto& rid : runs_consuming_[version_id]) {
            const std::string run_id = rid.get<std::string>();
            pwb::workspace::RunSummary summary;
            summary.id = run_id;
            summary.operation = run_meta_[run_id][0].get<std::string>();
            summary.status = run_meta_[run_id][1].get<std::string>();
            out.push_back(std::move(summary));
        }
        return out;
    }

    std::vector<std::string> versions_of_asset(
        const std::string& asset_id) const override {
        std::vector<std::string> out;
        if (!versions_by_asset_.contains(asset_id)) return out;
        for (const auto& vid : versions_by_asset_[asset_id]) {
            out.push_back(vid.get<std::string>());
        }
        return out;
    }

private:
    const Json& run_inputs_;
    const Json& runs_consuming_;
    const Json& versions_by_asset_;
    const Json& run_meta_;
};

std::string usage_sort_key(const pwb::workspace::VersionUsage& usage) {
    return usage.kind + "|" + usage.ref_id + "|" + usage.version_id;
}

// Python's natural collection order is not a frozen contract on the C++
// side (std::map iterates by key); both sides are compared sorted.
std::vector<pwb::workspace::VersionUsage> sorted_usages(
    std::vector<pwb::workspace::VersionUsage> usages) {
    std::sort(usages.begin(), usages.end(),
              [](const auto& a, const auto& b) {
                  return usage_sort_key(a) < usage_sort_key(b);
              });
    return usages;
}

Json usage_to_json(const pwb::workspace::VersionUsage& usage) {
    Json out = Json::object();
    out["kind"] = usage.kind;
    out["ref_id"] = usage.ref_id;
    out["label"] = usage.label;
    out["version_id"] = usage.version_id;
    out["stage"] = usage.stage;
    out["role"] = usage.role;
    out["status"] = usage.status;
    return out;
}

void check_usage_lists(const std::vector<pwb::workspace::VersionUsage>& got,
                       const Json& expected, const std::string& tag) {
    std::vector<Json> expected_sorted;
    for (const auto& item : expected) expected_sorted.push_back(item);
    std::sort(expected_sorted.begin(), expected_sorted.end(),
              [](const Json& a, const Json& b) {
                  return (a["kind"].get<std::string>() + "|" +
                          a["ref_id"].get<std::string>() + "|" +
                          a["version_id"].get<std::string>()) <
                         (b["kind"].get<std::string>() + "|" +
                          b["ref_id"].get<std::string>() + "|" +
                          b["version_id"].get<std::string>());
              });
    PWB_CHECK(got.size() == expected_sorted.size());
    if (got.size() != expected_sorted.size()) {
        std::cout << "  " << tag << ": got " << got.size() << " usages, "
                  << "expected " << expected_sorted.size() << "\n";
        return;
    }
    for (std::size_t i = 0; i < got.size(); ++i) {
        const auto diff = json_compare(usage_to_json(got[i]),
                                       expected_sorted[i]);
        if (diff.has_value()) {
            std::cout << "  " << tag << " usage[" << i << "]: " << *diff
                      << "\n";
        }
        PWB_CHECK(!diff.has_value());
    }
}

}  // namespace

// The retired vocabularies (key primitives / key assignment / role
// bands / tree model / tree_from_nodes / keyed-LCS diff) were replayed
// here until the second layer tree was deleted; role-band spot checks
// now live in ui_composite.layer_control, tree truth in
// platform.layer_tree_composer.

PWB_TEST(source_usage_parity) {
    const Json& cases = oracle()["usage_cases"];
    pwb::domain::DiagnosticList diagnostics;
    pwb::workspace::MappingWorkspaceState workspace =
        pwb::workspace::MappingWorkspaceState::from_json(cases["workspace"],
                                                         diagnostics);
    const Json project = cases["project"];
    const FakeCatalog catalog(cases["catalog"]);
    for (const auto& query : cases["version_queries"]) {
        pwb::workspace::VersionUsageReport report =
            pwb::workspace::usages_of_version(
                query["version_id"].get<std::string>(), &workspace,
                query["with_project"].get<bool>() ? &project : nullptr,
                &catalog, query["include_runs"].get<bool>());
        PWB_CHECK(report.truncated == query["truncated"].get<bool>());
        check_usage_lists(sorted_usages(std::move(report.usages)),
                          query["expected"],
                          "version " + query["version_id"]
                              .get<std::string>());
    }
    for (const auto& query : cases["asset_queries"]) {
        pwb::workspace::VersionUsageReport report =
            pwb::workspace::usages_of_asset(
                query["asset_id"].get<std::string>(), &workspace,
                query["with_project"].get<bool>() ? &project : nullptr,
                query["with_catalog"].get<bool>() ? &catalog : nullptr);
        check_usage_lists(sorted_usages(std::move(report.usages)),
                          query["expected"],
                          "asset " + query["asset_id"].get<std::string>());
    }
}

PWB_TEST(stage_view_behavior_parity) {
    const Json& cases = oracle()["stage_view_cases"];

    auto parse_view = [](const Json& data) {
        pwb::workspace::StageViewState view;
        view.stage = data.value("stage", std::string());
        if (data.contains("group_visibility")) {
            for (auto it = data["group_visibility"].begin();
                 it != data["group_visibility"].end(); ++it) {
                if (it.value().is_null()) {
                    view.group_visibility[it.key()] = std::nullopt;
                } else {
                    view.group_visibility[it.key()] =
                        it.value().get<bool>();
                }
            }
        }
        if (data.contains("layer_visibility")) {
            for (auto it = data["layer_visibility"].begin();
                 it != data["layer_visibility"].end(); ++it) {
                if (it.value().is_null()) {
                    view.layer_visibility[it.key()] = std::nullopt;
                } else {
                    view.layer_visibility[it.key()] =
                        it.value().get<bool>();
                }
            }
        }
        if (data.contains("layer_opacity")) {
            for (auto it = data["layer_opacity"].begin();
                 it != data["layer_opacity"].end(); ++it) {
                if (it.value().is_null()) {
                    view.layer_opacity[it.key()] = std::nullopt;
                } else {
                    view.layer_opacity[it.key()] =
                        it.value().get<double>();
                }
            }
        }
        if (data.contains("active_layer_id") &&
            !data["active_layer_id"].is_null()) {
            view.active_layer_id =
                data["active_layer_id"].get<std::string>();
        }
        view.customized = data.value("customized", false);
        return view;
    };
    auto parse_bool_map = [](const Json& data) {
        std::map<std::string, bool> out;
        for (auto it = data.begin(); it != data.end(); ++it) {
            out[it.key()] = it.value().get<bool>();
        }
        return out;
    };
    auto map_to_json = [](const std::map<std::string, bool>& data) {
        Json out = Json::object();
        for (const auto& [key, value] : data) out[key] = value;
        return out;
    };

    {
        pwb::workspace::StageViewState view =
            parse_view(cases["effective"]["view"]);
        const auto effective = pwb::workspace::effective_group_visibility(
            view, parse_bool_map(cases["effective"]["defaults"]));
        const auto diff = json_compare(map_to_json(effective),
                                       cases["effective"]["expected"]);
        PWB_CHECK(!diff.has_value());
    }
    {
        pwb::workspace::StageViewState view =
            parse_view(Json{{"stage", "constraint_factor"}});
        for (const auto& op : cases["records"]["ops"]) {
            const std::string id = op["id"].get<std::string>();
            if (op["kind"] == "group_visibility") {
                pwb::workspace::record_group_visibility(
                    view, id, op["value"].get<bool>());
            } else if (op["kind"] == "layer_visibility") {
                pwb::workspace::record_layer_visibility(
                    view, id, op["value"].get<bool>());
            } else {
                pwb::workspace::record_layer_opacity(
                    view, id, op["value"].get<double>());
            }
        }
        const auto effective = pwb::workspace::effective_group_visibility(
            view, parse_bool_map(cases["records"]["effective_defaults"]));
        const auto diff = json_compare(map_to_json(effective),
                                       cases["records"]["expected_effective"]);
        PWB_CHECK(!diff.has_value());
        PWB_CHECK(view.customized == cases["records"]["customized"]
                                         .get<bool>());
        Json visibility = Json::object();
        for (const auto& [key, value] : view.layer_visibility) {
            if (value.has_value()) visibility[key] = *value;
        }
        PWB_CHECK(!json_compare(visibility,
                                cases["records"]["expected_visibility"])
                       .has_value());
        Json opacity = Json::object();
        for (const auto& [key, value] : view.layer_opacity) {
            if (value.has_value()) opacity[key] = *value;
        }
        PWB_CHECK(!json_compare(opacity,
                                cases["records"]["expected_opacity"])
                       .has_value());
    }
    {
        pwb::workspace::StageViewState view =
            parse_view(cases["reset"]["view"]);
        pwb::workspace::reset_stage_view_to_defaults(view);
        const auto effective = pwb::workspace::effective_group_visibility(
            view, parse_bool_map(cases["reset"]["defaults"]));
        const auto diff = json_compare(map_to_json(effective),
                                       cases["reset"]["expected_effective"]);
        PWB_CHECK(!diff.has_value());
        PWB_CHECK(view.customized ==
                  cases["reset"]["customized"].get<bool>());
    }
}
